import{_ as e,o as l,c as t,ag as i}from"./chunks/framework.DQQHyi2x.js";const p=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"features/plugins.md","filePath":"features/plugins.md"}'),n={name:"features/plugins.md"};function s(o,a,r,d,u,g){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>Browse, install, enable/disable, and update Claude Code plugins.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Plugins are packages that extend Claude Code with commands, skills, agents, MCP servers, and hooks. The Plugins page has three tabs:</p><ul><li><strong>Installed</strong> — manage your installed plugins</li><li><strong>Marketplace</strong> — browse and install from configured marketplaces</li><li><strong>All Available</strong> — search across all marketplaces</li></ul><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="viewing-installed-plugins" tabindex="-1">Viewing Installed Plugins <a class="header-anchor" href="#viewing-installed-plugins" aria-label="Permalink to &quot;Viewing Installed Plugins&quot;">​</a></h3><p>The Installed tab shows plugin cards with:</p><ul><li>Plugin name, version, and source badge</li><li>Category and scope (user/project/local)</li><li>Component summary (commands, skills, agents, etc.)</li><li>Enable/disable toggle</li><li>Update indicator (orange button when new version available)</li></ul><p>Filter by status (enabled/disabled), update availability, or source.</p><h3 id="installing-plugins" tabindex="-1">Installing Plugins <a class="header-anchor" href="#installing-plugins" aria-label="Permalink to &quot;Installing Plugins&quot;">​</a></h3><ol><li>Switch to the <strong>Marketplace</strong> tab</li><li>Select a marketplace from the dropdown</li><li>Browse or search for plugins</li><li>Click a plugin card to preview its README and details</li><li>Click <strong>Install</strong> to open the wizard</li><li>Choose installation scope (user, project, or local)</li><li>Wait for installation to complete</li></ol><h3 id="updating-plugins" tabindex="-1">Updating Plugins <a class="header-anchor" href="#updating-plugins" aria-label="Permalink to &quot;Updating Plugins&quot;">​</a></h3><ul><li>Click <strong>&quot;Check Updates&quot;</strong> in the bulk actions bar to scan for new versions</li><li>Update individual plugins with the orange update button on their card</li><li>Use <strong>&quot;Update All&quot;</strong> to batch-update all outdated plugins</li></ul><h3 id="bulk-operations" tabindex="-1">Bulk Operations <a class="header-anchor" href="#bulk-operations" aria-label="Permalink to &quot;Bulk Operations&quot;">​</a></h3><p>The actions bar supports:</p><ul><li><strong>Check Updates</strong> — scan all plugins for new versions</li><li><strong>Update All</strong> — update all outdated plugins at once</li><li><strong>Enable All / Disable All</strong> — toggle all plugins</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Location</th><th>Scope</th></tr></thead><tbody><tr><td><code>~/.claude/plugins/</code></td><td>User plugins</td></tr><tr><td><code>.claude/plugins/</code></td><td>Project plugins</td></tr><tr><td><code>~/.claude/settings.json</code> → <code>enabledPlugins</code></td><td>Enable/disable state</td></tr></tbody></table><p>Marketplace URLs are configured in Claude Code settings.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Local plugins</strong> can be uninstalled; marketplace plugins use enable/disable.</li><li>Plugin cards show component counts so you can see what a plugin provides at a glance.</li><li>Plugins can provide their own MCP servers — check the detail view for MCP badges.</li></ul>',22)])])}const h=e(n,[["render",s]]);export{p as __pageData,h as default};
